def build_zonal_grid():
    grid = []

    for ri in range(14):
        # Determine band this row belongs to
        if ri < 4:
            zone_vals = [1, 1, 4, 4]  # Bands 0-7 (rows 0-7): pattern
        elif ri < 8:
            zone_vals = [1, 1, 4, 4]  # Bands 0-7
        elif ri < 12:
            zone_vals = [5, 5, 4, 4]  # Bands 8-11
        else:
            zone_vals = [5, 5, 5, 5]  # Band 12-13

        # Fill entire row with zones
        row = []
        z_idx = 0
        for c in range(28):
            if z_idx < len(zone_vals):
                row.append(zone_vals[z_idx])
            else:
                row.append(zone_vals[-1])
            # Move to next zone after zone width cols
            # Zones: 0-7 (8 cols), 8-15 (8), 16-23 (8), 24-27 (4)
            if c == 7 or c == 15 or c == 23:
                z_idx += 1
        grid.append(row)

    return grid

